<template><ion-page><ion-content class="publico"><main><header><span>SYNER · CATÁLOGO PÚBLICO</span><h1>Encontrá tu próximo cupo</h1><p>Lotes disponibles de proveedores de la comunidad.</p></header><p v-if="cargando">Cargando catálogo…</p><p v-else-if="error">{{ error }}</p><section v-else class="grid"><article v-for="l in lotes" :key="l.nombre + l.fecha_fin"><img v-if="url_imagen_lote(l.imagen_avatar)" :src="url_imagen_lote(l.imagen_avatar) ?? undefined" :alt="`Imagen del lote ${l.nombre}`" loading="lazy"><small>{{ l.categoria }} · {{ l.proveedor }} <b v-if="l.proveedor_verificado">✓ Verificado</b></small><h2>{{ l.nombre }}</h2><p>{{ l.descripcion }}</p><strong>{{ moneda(l.precio_cupo) }}</strong><s>{{ moneda(l.precio_mercado) }}</s><span class="ahorro">{{ l.porcentaje_ahorro }}% de ahorro</span><footer>{{ l.cupos_disponibles }} cupos · Finaliza {{ new Date(l.fecha_fin).toLocaleDateString('es-AR') }}</footer></article></section><a href="https://syner-api.runasp.net/privacidad.html">Política de privacidad</a></main></ion-content></ion-page></template>
<script setup lang="ts">
import { onMounted, ref } from "vue"; import { IonContent, IonPage } from "@ionic/vue"; import { obtener } from "@/services/ajax_service"; import { url_imagen_lote } from "@/services/lotes_service";
interface LotePublico { nombre:string; descripcion:string; categoria:string; precio_cupo:number; precio_mercado:number; porcentaje_ahorro:number; cupos_disponibles:number; fecha_fin:string; proveedor:string; proveedor_verificado:boolean; imagen_avatar?:string|null }
const lotes=ref<LotePublico[]>([]), cargando=ref(true), error=ref(""); const moneda=(n:number)=>new Intl.NumberFormat("es-AR",{style:"currency",currency:"ARS",maximumFractionDigits:0}).format(n);
onMounted(async()=>{try{lotes.value=await obtener<LotePublico[]>("publico/lotes")}catch{error.value="No pudimos cargar el catálogo. Probá nuevamente más tarde."}finally{cargando.value=false}});
</script>
<style scoped>.publico{--background:#f4f7fb;color:#172033}.publico main{max-width:1050px;margin:auto;padding:32px 20px}.publico header{padding:28px;border-radius:24px;background:linear-gradient(135deg,#123a78,#2877d4);color:white}.publico header span{font-size:12px;letter-spacing:.14em}.publico h1{font-size:clamp(28px,6vw,46px);margin:10px 0}.publico .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:16px;margin:24px 0}.publico article{display:flex;flex-direction:column;gap:10px;padding:20px;border-radius:20px;background:white;box-shadow:0 12px 32px #15335a13}.publico article img{width:calc(100% + 40px);max-width:none;height:190px;margin:-20px -20px 4px;object-fit:cover;border-radius:20px 20px 0 0;background:#e9eef5}.publico small,.publico footer{color:#66758c}.publico article h2,.publico article p{margin:0}.publico article strong{font-size:24px}.publico article s{color:#78859a}.publico article b,.ahorro{color:#14845d}.publico footer{margin-top:auto;font-size:13px}</style>
